def string(key, lang):
    """STRINGS[key] in a game language (0 English .. 8 Spanish)"""
    if lang == 4:
        return STRINGS[key][1]
    if lang in TR_LANGS and key in TR:
        return TR[key][TR_LANGS.index(lang)]
    return STRINGS[key][0]
